import { IEnvironmentAware } from "../environment-aware";
import * as constructs from "constructs";
/**
 * Indicates that this resource can be referenced as a Dataset.
 *
 * @stability experimental
 */
export interface IDatasetRef extends constructs.IConstruct, IEnvironmentAware {
    /**
     * A reference to a Dataset resource.
     */
    readonly datasetRef: DatasetReference;
}
/**
 * A reference to a Dataset resource.
 *
 * @struct
 * @stability external
 */
export interface DatasetReference {
    /**
     * The Arn of the Dataset resource.
     */
    readonly datasetArn: string;
}
/**
 * Indicates that this resource can be referenced as a Namespace.
 *
 * @stability experimental
 */
export interface INamespaceRef extends constructs.IConstruct, IEnvironmentAware {
    /**
     * A reference to a Namespace resource.
     */
    readonly namespaceRef: NamespaceReference;
}
/**
 * A reference to a Namespace resource.
 *
 * @struct
 * @stability external
 */
export interface NamespaceReference {
    /**
     * The Arn of the Namespace resource.
     */
    readonly namespaceArn: string;
}
